/* Juniper EX configuration for erb-spine1 */
/* Hardware: EX4400-24T (member 0) */
/* Made by Multi-Vendor Switch Config Builder 0.2.0. Review before you commit. */
system {
    host-name erb-spine1;
    domain-name erb.lab.local;
    name-server {
        10.99.0.53;
        1.1.1.1;
    }
    domain-search erb.lab.local;
    ntp {
        server 10.99.0.123 prefer;
        server time.cloudflare.com;
    }
    login {
        message "EVPN-VXLAN ERB campus fabric lab. Gateways live on the leaves. Lab use only.";
        user labadmin {
            class super-user;
            authentication {
                encrypted-password "$6$UVR2Iqx4d5UDYzYU$.Wo5CPsfQwYn6rdZws5ASWUz5EGVA5e4Mv3FqI83g90smxAQE926mzzL.OAK9mPz6YbzERL35K.E.h3FugDp40";
            }
        }
        retry-options {
            tries-before-disconnect 3;
            backoff-threshold 2;
            lockout-period 5;
        }
    }
    management-instance;
    root-authentication {
        encrypted-password "$6$UVR2Iqx4d5UDYzYU$.Wo5CPsfQwYn6rdZws5ASWUz5EGVA5e4Mv3FqI83g90smxAQE926mzzL.OAK9mPz6YbzERL35K.E.h3FugDp40";
    }
    services {
        ssh {
            root-login deny;
            protocol-version v2;
            connection-limit 10;
            rate-limit 5;
        }
        netconf {
            ssh {
                port 830;
            }
        }
    }
    syslog {
        file messages {
            any notice;
            authorization info;
        }
        file interactive-commands {
            interactive-commands any;
        }
    }
}
interfaces {
    em0 {
        unit 0 {
            family inet {
                address 10.99.1.11/24;
            }
        }
    }
    xe-0/2/0 {
        description "Fabric link to erb-leaf1 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.1.0/31;
            }
        }
    }
    xe-0/2/1 {
        description "Fabric link to erb-leaf2 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.1.4/31;
            }
        }
    }
    xe-0/2/2 {
        description "Fabric link to erb-leaf3 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.1.8/31;
            }
        }
    }
    xe-0/2/3 {
        description "Fabric link to erb-leaf4 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.1.12/31;
            }
        }
    }
    lo0 {
        unit 0 {
            family inet {
                address 10.255.1.1/32;
            }
        }
    }
}
routing-instances {
    mgmt_junos {
        routing-options {
            static {
                route 0.0.0.0/0 next-hop 10.99.1.1;
            }
        }
    }
}
snmp {
    location "EVE-NG lab";
    contact noc@lab.local;
}
routing-options {
    router-id 10.255.1.1;
    autonomous-system 65100;
    forwarding-table {
        export ECMP-LOAD-BALANCE;
    }
}
policy-options {
    policy-statement ECMP-LOAD-BALANCE {
        then {
            load-balance per-packet;
        }
    }
    policy-statement UNDERLAY-EXPORT {
        term loopback {
            from {
                protocol direct;
                route-filter 10.255.1.1/32 exact;
            }
            then {
                accept;
            }
        }
    }
}
protocols {
    bgp {
        group UNDERLAY {
            type external;
            description "Fabric underlay";
            multipath multiple-as;
            bfd-liveness-detection {
                minimum-interval 1000;
            }
            export UNDERLAY-EXPORT;
            neighbor 10.254.1.1 {
                peer-as 65101;
            }
            neighbor 10.254.1.5 {
                peer-as 65102;
            }
            neighbor 10.254.1.9 {
                peer-as 65103;
            }
            neighbor 10.254.1.13 {
                peer-as 65104;
            }
        }
        group EVPN-OVERLAY {
            type external;
            description "EVPN overlay";
            local-address 10.255.1.1;
            family evpn {
                signaling;
            }
            multihop {
                no-nexthop-change;
            }
            neighbor 10.255.1.3 {
                peer-as 65101;
            }
            neighbor 10.255.1.4 {
                peer-as 65102;
            }
            neighbor 10.255.1.5 {
                peer-as 65103;
            }
            neighbor 10.255.1.6 {
                peer-as 65104;
            }
        }
    }
    lldp {
        interface all;
    }
    lldp-med {
        interface all;
    }
    rstp {
        interface all;
        bpdu-block-on-edge;
    }
}
forwarding-options {
    storm-control-profiles storm-default {
        all {
            bandwidth-percentage 5;
        }
    }
}

