        }
    }
}
interfaces {
    em0 {
        unit 0 {
            family inet {
                address 10.99.1.13/24;
            }
        }
    }
    irb {
        unit 110 {
            family inet {
                address 10.110.3.254/22 {
                    virtual-gateway-address 10.110.0.1;
                }
            }
        }
        unit 120 {
            family inet {
                address 10.120.1.254/23 {
                    virtual-gateway-address 10.120.0.1;
                }
            }
        }
        unit 130 {
            family inet {
                address 10.130.0.254/24 {
                    virtual-gateway-address 10.130.0.1;
                }
            }
        }
        unit 140 {
            family inet {
                address 10.140.3.254/22 {
                    virtual-gateway-address 10.140.0.1;
                }
            }
        }
        unit 210 {
            family inet {
                address 10.210.0.254/24 {
                    virtual-gateway-address 10.210.0.1;
                }
            }
        }
        unit 220 {
            family inet {
                address 10.220.0.254/24 {
                    virtual-gateway-address 10.220.0.1;
                }
            }
        }
        unit 310 {
            family inet {
                address 10.31.3.254/22 {
                    virtual-gateway-address 10.31.0.1;
                }
            }
        }
    }
    xe-0/2/0 {
        description "Fabric link to erb-spine1 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.1.1/31;
            }
        }
    }
    xe-0/2/1 {
        description "Fabric link to erb-spine2 port xe-0/2/0";
        mtu 9216;
        unit 0 {
            family inet {
                address 10.254.1.3/31;
            }
        }
    }
    interface-range {
        ACCESS {
            member-range ge-0/0/0 to ge-0/0/23;
            description "Access ports";
            unit 0 {
                family ethernet-switching {
                    interface-mode access;
                    vlan {
                        members CORP-USERS;
                    }
                    storm-control storm-default;
                }
            }
        }
    }
    xe-0/2/2 {
        ether-options {
            802.3ad ae1;
        }
    }
    ae1 {
        aggregated-ether-options {
            lacp {
                active;
                periodic fast;
                system-id 00:00:11:00:00:01;
            }
        }
        esi 00:11:00:00:00:00:00:00:00:01;
        esi {
            all-active;
        }
        description "ESI-LAG to erb-acc1 (all-active, same ESI on the leaf pair)";
        unit 0 {
            family ethernet-switching {
                interface-mode trunk;
                vlan {
                    members [ CORP-USERS CORP-VOICE CORP-PRINTERS CORP-WIFI IOT-CAMERAS IOT-BMS GUEST-WIFI ];
                }
            }
        }
    }
    xe-0/2/3 {
        ether-options {
            802.3ad ae2;
        }
    }
    ae2 {
        aggregated-ether-options {
            lacp {
                active;
                periodic fast;
                system-id 00:00:11:00:00:02;
            }
        }
        esi 00:11:00:00:00:00:00:00:00:02;
        esi {
            all-active;
        }
        description "ESI-LAG to erb-acc2 (all-active, same ESI on the leaf pair)";
        unit 0 {
            family ethernet-switching {
                interface-mode trunk;
                vlan {
                    members [ CORP-USERS CORP-VOICE CORP-PRINTERS CORP-WIFI IOT-CAMERAS IOT-BMS GUEST-WIFI ];
                }
            }
        }
    }
    lo0 {
        unit 0 {
            family inet {
                address 10.255.1.3/32;
            }
        }
        unit 11 {
            family inet;
        }
        unit 12 {
            family inet;
        }
        unit 13 {
            family inet;
        }
    }
}
routing-instances {
    mgmt_junos {
        routing-options {
            static {
                route 0.0.0.0/0 next-hop 10.99.1.1;
            }
        }
    }
    CORP {
        instance-type vrf;
        interface lo0.11;
        interface irb.110;
        interface irb.120;
        interface irb.130;
        interface irb.140;
        route-distinguisher 10.255.1.3:11;
        vrf-target target:65101:9001;
        protocols {
            evpn {
                ip-prefix-routes {
                    advertise direct-nexthop;
                    encapsulation vxlan;
                    vni 9001;
                }
            }
        }
    }
    IOT {
        instance-type vrf;
        interface lo0.12;
        interface irb.210;
        interface irb.220;
        route-distinguisher 10.255.1.3:12;
        vrf-target target:65101:9002;
        protocols {
            evpn {
                ip-prefix-routes {
                    advertise direct-nexthop;
                    encapsulation vxlan;
                    vni 9002;
                }
            }
        }
    }
    GUEST {
        instance-type vrf;
        interface lo0.13;
        interface irb.310;
        route-distinguisher 10.255.1.3:13;
        vrf-target target:65101:9003;
        protocols {
            evpn {
                ip-prefix-routes {
                    advertise direct-nexthop;
                    encapsulation vxlan;
                    vni 9003;
                }
            }
        }
    }
}
snmp {
    location "EVE-NG lab";
    contact noc@lab.local;
}
vlans {
    CORP-USERS {
        description "VNI 10110";
        vlan-id 110;
        l3-interface irb.110;
        vxlan {
            vni 10110;
        }
    }
    CORP-VOICE {
        description "VNI 10120";
        vlan-id 120;
        l3-interface irb.120;
        vxlan {
            vni 10120;
        }
    }
    CORP-PRINTERS {
        description "VNI 10130";
        vlan-id 130;
        l3-interface irb.130;
        vxlan {
            vni 10130;
        }
    }
    CORP-WIFI {
        description "VNI 10140";
        vlan-id 140;
        l3-interface irb.140;
        vxlan {
            vni 10140;
        }
    }
    IOT-CAMERAS {
        description "VNI 10210";
        vlan-id 210;
        l3-interface irb.210;
        vxlan {
            vni 10210;
        }
    }
    IOT-BMS {
        description "VNI 10220";
        vlan-id 220;
        l3-interface irb.220;
        vxlan {
            vni 10220;
        }
    }
    GUEST-WIFI {
        description "VNI 10310";
        vlan-id 310;
        l3-interface irb.310;
        vxlan {
            vni 10310;
        }
    }
}
chassis {
    aggregated-devices {
        ethernet {
            device-count 3;
        }
    }
