                signaling;
            }
            multipath multiple-as;
            multihop {
                no-nexthop-change;
            }
            neighbor 10.255.1.1 {
                peer-as 65100;
            }
            neighbor 10.255.1.2 {
                peer-as 65100;
            }
        }
    }
    evpn {
        encapsulation vxlan;
        extended-vni-list all;
        default-gateway {
