            edge;
        }
        interface ge-0/0/18 {
            edge;
        }
        interface ge-0/0/19 {
            edge;
        }
        interface ge-0/0/20 {
            edge;
        }
        interface ge-0/0/21 {
            edge;
        }
        interface ge-0/0/22 {
            edge;
        }
        interface ge-0/0/23 {
            edge;
        }
