    }
}
switch-options {
    vtep-source-interface lo0.0;
    route-distinguisher 10.255.1.3:1;
    vrf-target target:65100:1;
}
forwarding-options {
    storm-control-profiles storm-default {
        all {
            bandwidth-percentage 5;
        }
    }
